import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { spawn } from 'node:child_process';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  const submissionPath = join(submissionDir, 'answer.mjs');
  const pinnedPath = join(referenceDir, 'pinned-test-cases.txt');
  if (!existsSync(submissionPath)) return { accept: false, reason: 'missing answer.mjs' };
  if (!existsSync(pinnedPath)) return { accept: false, reason: 'missing pinned-test-cases.txt' };

  const pinnedTests = readFileSync(pinnedPath, 'utf8');
  const runnerPath = join(referenceDir, 'gate-runner.mjs');
  const subUrl = pathToFileURL(submissionPath).href;

  const runnerSrc = [
    'import assert from \'node:assert/strict\';',
    'let dedupeSorted;',
    'try {',
    '  const mod = await import(' + JSON.stringify(subUrl) + ');',
    '  dedupeSorted = mod.dedupeSorted;',
    '} catch (e) {',
    '  console.error(\'IMPORT_FAIL\', e && (e.message || String(e)));',
    '  process.exit(2);',
    '}',
    'if (typeof dedupeSorted !== \'function\') {',
    '  console.error(\'NOT_A_FUNCTION\');',
    '  process.exit(2);',
    '}',
    'const failures = [];',
    'function test(name, fn) {',
    '  try {',
    '    const ret = fn();',
    '    if (ret && typeof ret.then === \'function\') { throw new Error(\'async test\'); }',
    '  } catch (e) {',
    '    failures.push(String(name) + \': \' + (e && e.message ? e.message : String(e)));',
    '  }',
    '}',
    pinnedTests,
    'function oracle(arr) {',
    '  const out = [];',
    '  for (let i = 0; i < arr.length; i++) {',
    '    if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);',
    '  }',
    '  return out;',
    '}',
    'function check(name, arr) {',
    '  test(name, () => { assert.deepStrictEqual(dedupeSorted(arr.slice()), oracle(arr)); });',
    '}',
    'check(\ 'extra-zeros\', [0, 0, 0]);',
    'check(\'extra-neg\', [-5, -5, -1, -1, 3]);',
    'check(\'extra-spread\', [1, 1, 2, 3, 3, 3, 4, 4]);',
    'for (let trial = 0; trial < 40; trial++) {',
    '  const len = Math.floor(Math.random() * 25);',
    '  const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 15) - 7).sort((a, b) => a - b);',
    '  check(\'extra-random-\' + trial, arr);',
    '}',
    'if (failures.length) { console.error(failures.join(\'\\n\')); process.exit(1); }',
    'process.exit(0);',
  ].join('\n');

  writeFileSync(runnerPath, runnerSrc, 'utf8');

  const outcome = await new Promise((resolve) => {
    const child = spawn(process.execPath, [runnerPath], { stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    let done = false;
    const finish = (r) => { if (!done) { done = true; resolve(r); } };
    const t = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} finish({ ok: false, detail: 'timeout' }); }, 15000);
    child.stdout.on('data', (d) => { stdout += d.toString(); });
    child.stderr.on('data', (d) => { stderr += d.toString(); });
    child.on('close', (code) => { clearTimeout(t); finish({ ok: code === 0, detail: (stderr + '\n' + stdout).trim().slice(0, 600) }); });
    child.on('error', (e) => { clearTimeout(t); finish({ ok: false, detail: String(e && e.message ? e.message : e) }); });
  });

  if (outcome.ok) return { accept: true, reason: 'all pinned tests passed' };
  return { accept: false, reason: 'pinned tests failed: ' + (outcome.detail || 'non-zero exit') };
}

